// Multiple classes in one file for the runnable demo.
package com.bank.loan;

import java.math.BigDecimal;
import java.util.logging.*;

public class ReorderDemo {
    private static final Logger log = Logger.getLogger(ReorderDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Loan queue in arrival order: L1 .. L6
        LoanNode head = build(
            new String[]{"L1", "L2", "L3", "L4", "L5", "L6"},
            new String[]{"100000", "200000", "300000", "400000", "500000", "600000"});

        log.info("Reordering loan queue to pair earliest with latest (L0,Ln,L1,Ln-1,...)");
        QueueReorderService service = new QueueReorderService();
        service.reorder(head);

        for (LoanNode n = head; n != null; n = n.next) {
            final LoanNode cur = n;
            log.info(() -> "Review order -> " + cur.appId + " amount Rs." + cur.amount);
        }
        log.info("Loan review queue reordered successfully");
    }

    private static LoanNode build(String[] ids, String[] amounts) {
        LoanNode dummy = new LoanNode(null, BigDecimal.ZERO);
        LoanNode tail = dummy;
        for (int i = 0; i < ids.length; i++) {
            tail.next = new LoanNode(ids[i], new BigDecimal(amounts[i]));
            tail = tail.next;
        }
        return dummy.next;
    }
}

