class LoanNode {
    String appId;
    BigDecimal amount;
    LoanNode next;

    LoanNode(String appId, BigDecimal amount) {
        this.appId = appId;
        this.amount = amount;
    }
}

// ─── Would be in service/QueueReorderService.java ───
class QueueReorderService {
    // Reorder to L0,Ln,L1,Ln-1,... in place. O(n) time, O(1) space.
    void reorder(LoanNode head) {
        if (head == null || head.next == null) return;

        // Phase 1: find the end of the first half
        LoanNode slow = head, fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        // Split into two halves
        LoanNode second = slow.next;
        slow.next = null;

        // Phase 2: reverse the second half
        LoanNode prev = null, curr = second;
        while (curr != null) {
            LoanNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        second = prev;

        // Phase 3: merge the two halves by alternating nodes
        LoanNode first = head;
        while (second != null) {
            LoanNode f = first.next;   // save
            LoanNode s = second.next;  // save
            first.next = second;       // front -> back
            second.next = f;           // back -> next front
            first = f;
            second = s;
        }
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
